 let connection=newConnection();
 const prefs=()=>({language:'en',alertsEnabled:true,syncInterval:5,quietHours:false,backgroundFrost:60,subscription:'free',backgroundMode:'neutral',backgroundPhoto:'',backgroundProfilePhoto:'',pawPattern:true,...(getStore().preferences||{})});
 const lang=()=>prefs().language==='zh'?'zh':'en';
 const t=key=>dictionary[lang()][key]||dictionary.en[key]||key;
