 const subscriptionDemo=createSubscriptionDemo({getAccount,getLanguage:lang,openCheckout:openDemoCheckout,onChange:()=>{if(!root.hidden&&section==='subscription'){render();(root.querySelector('.settings-demo-receipt')||root.querySelector('[data-demo-subscribe]'))?.focus({preventScroll:true});}}});
 const canReadBilling=()=>Boolean(getAccount()?.id&&!getAccount()?.isTest&&!getAccount()?.demo);
