 const shortTime=value=>{if(!value)return '—';const date=new Date(value);return Number.isFinite(date.valueOf())?new Intl.DateTimeFormat(lang()==='zh'?'zh-CN':'en-GB',{hour:'2-digit',minute:'2-digit'}).format(date):'—';};
 function notify(message,isError=false){const node=root.querySelector('.settings-feedback');if(!node)return;node.textContent=message;node.classList.toggle('is-error',isError);clearTimeout(feedbackTimer);if(!isError)feedbackTimer=setTimeout(()=>{node.textContent='';},4500);}
 async function save(next, message=t('saved')) { const result=await saveStore(next);if(result===false)throw new Error(t('saveFailed'));if(message)notify(message); }
 async function setPreference(key,value,{rerender=false}={}) {try{await save({...getStore(),preferences:{...prefs(),[key]:value}},'');if(key==='language')onLanguageChange?.(value);if(rerender)render();notify(key==='language'?t('languageSaved'):t('saved'));}catch(error){notify(error.message||t('saveFailed'),true);}}
 const switchRow=(key,title,note='')=>`<label class="settings-switch-row"><span><strong>${t(title)}</strong>${note?`<small>${t(note)}</small>`:''}</span><span class="settings-switch"><input type="checkbox" data-pref="${key}" ${prefs()[key]?'checked':''}><i aria-hidden="true"></i></span></label>`;

 const field=(name,label,value,extra='')=>`<label class="settings-field"><span>${t(label)}</span><input name="${name}" value="${esc(value)}" ${extra}></label>`;
